"""Generate the portable XJB tables from the checked-in C# tables."""

import argparse
from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "src/LuminPack.Core/Core/Json/Xjb/XjbTables.g.cs"
LICENSE = ROOT / "docs/xjb-LICENSE.txt"
NOTICE = (
    "// Generated by tools/xjb-tables/emit_portable.py from the C# XJB tables.\n"
    "// XJB by xjb714, commit 80cc89574a8f8457ffbf951afa2fd27c2459bd4a.\n"
    "// See docs/xjb-LICENSE.txt for the upstream license.\n"
)


def parse(text, name, count):
    match = re.search(rf"\b{name}\s*=\s*\{{([^}}]+)\}};", text)
    if match is None:
        raise ValueError(f"Missing C# table {name}.")
    tokens = re.findall(r"\b0x[0-9a-fA-F]+|\b[0-9]+\b", match[1])
    values = [int(token, 0) for token in tokens]
    if len(values) != count:
        raise ValueError(f"Expected {count} entries in {name}, got {len(values)}.")
    return values


def rows(values, prefix, suffix, indent, width):
    if prefix:
        tokens = [f"{prefix}{value:016X}{suffix}" for value in values]
    else:
        tokens = [str(value) for value in values]
    return "\n".join(indent + ", ".join(tokens[index:index + width]) + "," for index in range(0, len(tokens), width))


def render_cpp(tables):
    output = [NOTICE, "#pragma once\n\n#include <array>\n#include <cstdint>\n\nnamespace luminpack::detail\n{"]
    for name, values, byte in tables:
        kind = "uint8_t" if byte else "uint64_t"
        output.extend((f"inline constexpr std::array<std::{kind}, {len(values)}> {name}{{",
                       rows(values, "" if byte else "0x", "ULL", "    ", 16 if byte else 4), "};\n"))
    return "\n".join(output + ["}", ""])


def render_c(tables):
    output = [NOTICE, "#pragma once\n\n#include <stdint.h>\n"]
    for name, values, byte in tables:
        kind = "uint8_t" if byte else "uint64_t"
        output.extend((f"static const {kind} {name}[{len(values)}] = {{",
                       rows(values, "" if byte else "0x", "ULL", "    ", 16 if byte else 4), "};\n"))
    return "\n".join(output)


def render_go(tables):
    names = ("xjbFloat32Pow10", "xjbFloat32H37", "xjbFloat64Pow10")
    output = [NOTICE, "package luminpack\n"]
    for name, (_, values, byte) in zip(names, tables):
        kind = "uint8" if byte else "uint64"
        output.extend((f"var {name} = [...]{kind}{{",
                       rows(values, "" if byte else "0x", "", "\t", 16 if byte else 4), "}\n"))
    return "\n".join(output)


def render_java(tables):
    output = [NOTICE, "package luminpack;\n\nfinal class XjbTables {\n    private XjbTables() {}\n"]
    for name, values, byte in tables:
        kind = "int" if byte else "long"
        output.extend((f"    static final {kind}[] {name.upper()} = {{",
                       rows(values, "" if byte else "0x", "L", "        ", 16 if byte else 4), "    };\n"))
    return "\n".join(output + ["}", ""])


def render_typescript(tables):
    names = ("float32Pow10", "float32H37", "float64Pow10")
    output = [NOTICE.rstrip(), ""]
    for name, (_, values, byte) in zip(names, tables):
        kind = "Uint8Array" if byte else "BigUint64Array"
        output.extend((f"export const {name} = new {kind}([",
                       rows(values, "" if byte else "0x", "n", "    ", 16 if byte else 4), "]);\n"))
    return "\n".join(output)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Report generated files that differ from the C# tables.")
    args = parser.parse_args()

    text = SOURCE.read_text(encoding="utf-8-sig")
    tables = (("float32_pow10", parse(text, "Pow10Reverse", 77), False),
              ("float32_h37", parse(text, "H37", 256), True),
              ("float64_pow10", parse(text, "Pow10", 1234), False))
    outputs = {
        "src/LuminPack.Cpp/include/luminpack/detail/xjb_tables.h": render_cpp(tables),
        "src/LuminPack.Go/xjb_tables.go": render_go(tables),
        "src/LuminPack.Java/src/main/java/luminpack/XjbTables.java": render_java(tables),
        "src/LuminPack.TypeScript/src/xjb-tables.ts": render_typescript(tables),
        "src/LuminPack.TypeScript/wasm/xjb-tables.h": render_c(tables),
        "src/LuminPack.Go/LICENSE-xjb.txt": LICENSE.read_text(encoding="utf-8"),
        "src/LuminPack.TypeScript/LICENSE-xjb.txt": LICENSE.read_text(encoding="utf-8"),
    }
    differs = []
    for name, content in outputs.items():
        path = ROOT / name
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                differs.append(name)
        else:
            path.write_text(content, encoding="utf-8", newline="\n")
    if differs:
        raise SystemExit("Stale portable XJB tables:\n" + "\n".join(differs))


if __name__ == "__main__":
    main()
